pip3 list 2>/dev/null | head -60; echo "---check specific libs---"; python3 - <<'EOF'
for mod in ["plotly","seaborn","altair","bokeh","matplotlib","PIL","cairosvg","PIL.Image"]:
    try:
        m = __import__(mod)
        print(mod, "OK", getattr(m, "__version__", ""))
    except Exception as e:
        print(mod, "MISSING")
EOF
